export interface IndexOptions { full?: boolean; }

export interface IndexResult {
  files: number;
  chunks: number;
  dim: number;
  /** chunks reused from unchanged files (0 on fresh/full builds) */
  kept: number;
  /** chunks embedded this run */
  embedded: number;
  /** true when an existing compatible index was reused */
  incremental: boolean;
}

export async function indexRepo(
  root: string,
  embedder: Embedder,
  onProgress?: (msg: string) => void,
  opts: IndexOptions = {},
): Promise<IndexResult> {

const store = new EmberStore(root);

// Load previous index state for incremental reuse.
let oldChunks: ChunkRecord[] = [];
let oldHashes: FileHashMap = {};
let oldMeta: IndexMeta | null = null;
let oldIndex: HnswIndex | null = null;

        const loaded = await store.load();
        oldChunks = loaded.chunks;
        oldIndex = loaded.index;
        oldHashes = (await store.loadFileHashes()) ?? {};
      } catch {
        log("existing index unreadable - falling back to a full re-index");
        oldChunks = [];
      }
    } else {
      log(`embedder changed (${oldMeta.embedderKind} dim=${oldMeta.dim} -> ${embedder.kind} dim=${embedder.dim}) - full re-index`);
    }
  }
}

const files = await scanRepo(root);
const newHashes: FileHashMap = {};
for (const f of files) newHashes[f.relPath] = { sha1: sha1(f.content), size: f.content.length };

// Kept chunks: file still present with the same sha1; vectors reused.
const kept: ChunkRecord[] = [];
const keptVectors: Float32Array[] = [];

    const v = oldIndex!.getVector(c.id);
    if (!v) continue;
    kept.push(c);
    keptVectors.push(v);
  }
}

const changed = files.filter(f => oldHashes[f.relPath]?.sha1 !== newHashes[f.relPath].sha1);
log(`${files.length} files: ${files.length - changed.length} unchanged (${kept.length} chunks kept), ${changed.length} new/changed`);

// Reassign sequential ids; vectors stay aligned with chunks.
const chunks: ChunkRecord[] = [];
const vectors: Float32Array[] = [];

for (let i = 0; i < kept.length; i++) {
  chunks.push({ ...kept[i], id: chunks.length });
  vectors.push(keptVectors[i]);
  index.add(chunks.length - 1, keptVectors[i]);
}

const fresh: CodeChunk[] = [];
for (const f of changed) for (const c of chunkFile(f.relPath, f.content)) fresh.push(c);

    const vs = await embedder.embed(inputs);
    vs.forEach((v, j) => {
      chunks.push({ ...batch[j], id: chunks.length });
      vectors.push(v);
      index.add(chunks.length - 1, v);
    });
    if (fresh.length > BATCH) log(`embedded ${Math.min(i + BATCH, fresh.length)}/${fresh.length}`);
  }
}

  const now = new Date().toISOString();
  const meta: IndexMeta = {
    version: 1,
    repoRoot: root,
    embedderKind: embedder.kind,
    dim: embedder.dim,
    chunkCount: chunks.length,
    fileCount: files.length,
    createdAt: oldMeta?.createdAt ?? now,
    updatedAt: now,
  };
  await store.save(meta, chunks, vectors, index, newHashes);
  return {
    files: files.length,
    chunks: chunks.length,
    dim: embedder.dim,
    kept: kept.length,
    embedded: fresh.length,
    incremental: canReuse,
  };
}

/** OpenAI-compatible provider client (chat + embeddings) with honest
 * failure semantics, usage accounting and process-level request guards.
 *
 * What the guards ARE: EMBER_MAX_CALLS caps provider requests per process
 * and EMBER_MAX_PROMPT_CHARS caps input size per call. Both actually block
 * the request they name.
 * What they are NOT: billing limits. Ember never sees provider billing;
 * real spend is only on the provider's dashboard. Usage records say
 * "estimated" whenever a token figure is a chars/4 approximation rather
 * than provider-reported usage. */

// Node builtins are imported lazily inside the methods that need them, so
// this module stays loadable in non-Node bundles (the browser demo imports
// embedder.ts, which imports this file) as long as no Node-only path runs.

export interface LlmConfig {
  /** Base URL of an OpenAI-compatible API, e.g. https://openrouter.ai/api/v1 */
  base: string;
  apiKey: string;
  embedModel?: string;
  embedDim?: number;
  chatModel?: string;
  /** Max provider requests this process may make (EMBER_MAX_CALLS). */
  maxCalls?: number;
  /** Max input characters per request (EMBER_MAX_PROMPT_CHARS). */
  maxPromptCharsPerCall?: number;
}

export interface UsageRecord {
  ts: string;
  kind: "embed" | "chat";
  model: string;
  /** Host of the configured base URL - where the request went. */
  provider: string;
  items: number;
  /** Provider-reported token counts, when the API returned a usage object. */
  inputTokens?: number;
  outputTokens?: number;
  /** chars/4 approximation, present only when the provider reported nothing. */
  estimatedInputTokens?: number;
  /** true when any token figure above is an estimate, not provider-reported. */
  estimated: boolean;
  ok: boolean;
  error?: string;
}

export class JsonlUsageLogger implements UsageLogger {
  constructor(readonly file: string) {}
  static forRepo(repoRoot: string): JsonlUsageLogger {
    return new JsonlUsageLogger(`${repoRoot}/.ember/usage.jsonl`);
  }
  async log(r: UsageRecord): Promise<void> {
    // Resolved through Function so non-Node builds (browser demo bundle, no
    // @types/node) never have to resolve the specifier at compile time; in
    // the browser this code path simply never runs.
    const fs: any = await (new Function('return import("node:fs/promises")')());

    const dir = this.file.slice(0, this.file.lastIndexOf("/"));
    await fs.mkdir(dir, { recursive: true });
    await fs.appendFile(this.file, JSON.stringify(r) + "\n");
  }
}

export interface ChatResult {
  content: string;
  inputTokens?: number;
  outputTokens?: number;
  providerReported: boolean;
}

export class LlmClient {
  private calls = 0;
  /** Provider requests are serialized through this chain: one in flight per
   * client, so concurrency 1 is enforced, not just customary. */
  private queue: Promise<unknown> = Promise.resolve();
  constructor(
    readonly cfg: LlmConfig,
    private usage: UsageLogger = new NullUsageLogger(),
    private fetchFn: typeof fetch = fetch,
  ) {}

  private providerHost(): string {
    try { return new URL(this.cfg.base).host; } catch { return this.cfg.base; }
  }

  /** Guards that genuinely block the named request. Not billing limits. */
  private guard(inputChars: number): void {

if (this.cfg.maxCalls !== undefined && this.calls >= this.cfg.maxCalls) {
  throw new Error(
    `request blocked: EMBER_MAX_CALLS=${this.cfg.maxCalls} reached. This guard caps provider requests per process (it does not track or limit spending - check the provider dashboard for real billing). Raise or unset it to continue.`
  );
}

  if (this.cfg.maxPromptCharsPerCall !== undefined && inputChars > this.cfg.maxPromptCharsPerCall) {
    throw new Error(
      `request blocked: input is ${inputChars} chars, over EMBER_MAX_PROMPT_CHARS=${this.cfg.maxPromptCharsPerCall}. Narrow the query or raise the cap.`
    );
  }
}

private post(urlPath: string, body: unknown): Promise<Response> {

  const run = this.queue.then(() => this.postImmediate(urlPath, body));
  this.queue = run.catch(() => {});
  return run;
}

private async postImmediate(urlPath: string, body: unknown): Promise<Response> {

for (let attempt = 0; attempt < 2; attempt++) {
  this.calls++;
  let res: Response;
  try {
    res = await this.fetchFn(url, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${this.cfg.apiKey}`,
      },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (e) {
    lastErr = new Error(`endpoint unreachable (${this.providerHost()}): ${e instanceof Error ? e.message : String(e)}`);
    if (attempt === 0) { await new Promise(r => setTimeout(r, 1000)); continue; }
    throw lastErr;
  }
  if (res.ok) return res;

    const text = await res.text().catch(() => "");
    lastErr = new Error(`endpoint ${res.status}: ${text.slice(0, 500)}`);
    if (RETRYABLE.has(res.status) && attempt === 0) { await new Promise(r => setTimeout(r, 1000)); continue; }
    throw lastErr;
  }
  throw lastErr ?? new Error("request failed");
}

async chat(messages: ChatMessage[], opts: { maxTokens?: number; temperature?: number } = {}): Promise<ChatResult> {
  if (!this.cfg.chatModel) throw new Error("no chat model configured (EMBER_CHAT_MODEL)");

const model = this.cfg.chatModel;
const rec: UsageRecord = {
  ts: new Date().toISOString(), kind: "chat", model,
  provider: this.providerHost(), items: messages.length,
  estimated: false, ok: false,
};
try {

const res = await this.post("/chat/completions", {
  model,
  temperature: opts.temperature ?? 0.2,
  ...(opts.maxTokens ? { max_tokens: opts.maxTokens } : {}),
  messages,
});

const data = await res.json() as {
  choices: { message: { content: string } }[];
  usage?: { prompt_tokens?: number; completion_tokens?: number };
};

const content = data.choices[0]?.message?.content ?? "";
if (!content.trim()) throw new Error("chat endpoint returned an empty answer");
rec.ok = true;

    if (data.usage?.prompt_tokens !== undefined) {
      rec.inputTokens = data.usage.prompt_tokens;
      rec.outputTokens = data.usage.completion_tokens;
      rec.estimated = false;
    } else {
      rec.estimatedInputTokens = Math.ceil(inputChars / 4);
      rec.estimated = true;
    }
    return { content, inputTokens: rec.inputTokens, outputTokens: rec.outputTokens, providerReported: !rec.estimated };
  } catch (e) {
    rec.error = e instanceof Error ? e.message : String(e);
    throw e;
  } finally {
    await this.usage.log(rec).catch(() => {});
  }
}

/** Raw embeddings call; dimension validation stays with the caller. */
async embedRaw(texts: string[]): Promise<number[][]> {
  if (!this.cfg.embedModel) throw new Error("no embedding model configured (EMBER_EMBED_MODEL)");

const model = this.cfg.embedModel;
const rec: UsageRecord = {
  ts: new Date().toISOString(), kind: "embed", model,
  provider: this.providerHost(), items: texts.length,
  estimated: false, ok: false,
};
try {

const data = await res.json() as {
  data: { embedding: number[] }[];
  usage?: { prompt_tokens?: number; total_tokens?: number };
};
rec.ok = true;

      const reported = data.usage?.prompt_tokens ?? data.usage?.total_tokens;
      if (reported !== undefined) { rec.inputTokens = reported; rec.estimated = false; }
      else { rec.estimatedInputTokens = Math.ceil(inputChars / 4); rec.estimated = true; }
      return data.data.map(d => d.embedding);
    } catch (e) {
      rec.error = e instanceof Error ? e.message : String(e);
      throw e;
    } finally {
      await this.usage.log(rec).catch(() => {});
    }
  }
}

  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : undefined;
}

/** Build provider config from the environment, or null when unconfigured
 * (offline mode). EMBER_API_BASE is the single base URL; EMBER_CHAT_BASE is
 * still honored for backward compatibility. */

export function llmConfigFromEnv(
  env: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): LlmConfig | null {

  const embedDim = parseOptInt(env.EMBER_EMBED_DIM);
  return {
    base, apiKey,
    embedModel: env.EMBER_EMBED_MODEL || undefined,
    embedDim: embedDim,
    chatModel: env.EMBER_CHAT_MODEL || undefined,
    maxCalls: parseOptInt(env.EMBER_MAX_CALLS),
    maxPromptCharsPerCall: parseOptInt(env.EMBER_MAX_PROMPT_CHARS),
  };
}

/**
 * Cross-session agent notes. An agent leaves short factual notes for its next
 * session (decisions, gotchas, task state); they persist in
 * <repo>/.ember/notes.jsonl and survive restarts and other agents.
 * Search is deterministic lexical overlap - no embedder involved.
 */

import { promises as fs } from "node:fs";
import * as path from "node:path";

export interface Note {
  id: number;
  ts: string;
  text: string;
  tags: string[];
}

constructor(readonly repoRoot: string) {
  this.file = path.join(repoRoot, ".ember", "notes.jsonl");
}

private async readAllStats(): Promise<{ notes: Note[]; skipped: number }> {
  let raw: string;
  try { raw = await fs.readFile(this.file, "utf8"); }
  catch { return { notes: [], skipped: 0 }; }
  // A torn line (interrupted append) must not lose the whole history:
  // skip unparseable lines, keep the rest - but count the loss so it
  // can be surfaced instead of failing silently.
  const notes: Note[] = [];

  let skipped = 0;
  for (const l of raw.trim().split("\n")) {
    if (!l) continue;
    try { notes.push(JSON.parse(l) as Note); } catch { skipped++; }
  }
  return { notes, skipped };
}

private async readAll(): Promise<Note[]> {
  return (await this.readAllStats()).notes;
}

/** Unreadable lines in notes.jsonl (e.g. torn by an interrupted append). */
async corruptLineCount(): Promise<number> {
  return (await this.readAllStats()).skipped;
}

async add(text: string, tags: string[] = []): Promise<Note> {

const notes = await this.readAll();
const note: Note = {
  id: notes.length ? Math.max(...notes.map(n => n.id)) + 1 : 1,
  ts: new Date().toISOString(),
  text,
  tags,
};
await fs.mkdir(path.dirname(this.file), { recursive: true });
// If a previous append was interrupted mid-line, the file ends without a
// newline; appending directly would glue this record onto the torn tail
// and lose it. Repair the boundary first.

        const last = Buffer.alloc(1);
        await fd.read(last, 0, 1, st.size - 1);
        if (last[0] !== 0x0a) await fs.appendFile(this.file, "\n");
      }
    } finally { await fd.close(); }
  }
  await fs.appendFile(this.file, JSON.stringify(note) + "\n");
  return note;
}

/** Most recent first. */
async list(limit = 20): Promise<Note[]> {

  const notes = await this.readAll();
  return notes.slice(-limit).reverse();
}

/** Deterministic lexical scoring: unique query terms present in text+tags. */
async search(query: string, limit = 5): Promise<NoteHit[]> {

const terms = [...new Set(query.toLowerCase().split(/[^a-z0-9_]+/).filter(t => t.length > 1))];
if (terms.length === 0) return [];
const hits: NoteHit[] = [];
for (const n of await this.readAll()) {

      const score = terms.filter(t => hay.includes(t)).length;
      if (score > 0) hits.push({ ...n, score });
    }
    hits.sort((a, b) => b.score - a.score || b.ts.localeCompare(a.ts));
    return hits.slice(0, limit);
  }
}

/** Repo map: structure, entry points, key symbols, and hub files - the things
 * an agent otherwise burns its first N tool calls discovering. */

import { promises as fs } from "node:fs";
import * as path from "node:path";
import type { ChunkRecord } from "./store.js";

export interface RepoMap {
  totalFiles: number;
  totalChunks: number;
  filesByLanguage: Record<string, number>;
  topDirectories: { dir: string; files: number }[];
  entryPoints: string[];
  hubFiles: { file: string; referencedBy: number }[];
  symbols: { file: string; names: string[] }[];
}

  const ext = path.extname(f).slice(1) || "other";
  filesByLanguage[ext] = (filesByLanguage[ext] ?? 0) + 1;
}

  const d = path.dirname(f).split(path.sep)[0] || ".";
  dirCount.set(d, (dirCount.get(d) ?? 0) + 1);
}

const topDirectories = [...dirCount.entries()].map(([dir, n]) => ({ dir, files: n }))
  .sort((a, b) => b.files - a.files).slice(0, 12);

const entryPoints: string[] = [];

  const base = path.basename(f, path.extname(f)).toLowerCase();
  if (ENTRY_NAMES.has(base)) entryPoints.push(f);
}
try {

  const pkg = JSON.parse(await fs.readFile(path.join(root, "package.json"), "utf8"));
  if (pkg.main) entryPoints.push(String(pkg.main));
  if (pkg.bin) for (const v of Object.values(pkg.bin)) entryPoints.push(String(v));
} catch { /* not a node repo */ }

// hub files: referenced by import specifiers of other files (approximate, basename match)

  const stem = path.basename(f).replace(/\.[^.]+$/, "");
  if (!byStem.has(stem)) byStem.set(stem, []);
  byStem.get(stem)!.push(f);
}

for (const [f, text] of perFileText) {
  let m;
  IMPORT_RE.lastIndex = 0;
  while ((m = IMPORT_RE.exec(text)) !== null) {

    for (const t of targets) {
      if (t === f) continue;
      if (!refCount.has(t)) refCount.set(t, new Set());
      refCount.get(t)!.add(f);
    }
  }
}

const hubFiles = [...refCount.entries()]
  .map(([file, set]) => ({ file, referencedBy: set.size }))
  .sort((a, b) => b.referencedBy - a.referencedBy).slice(0, 10);

for (const c of chunks) {
  if (!c.symbol) continue;
  if (!symMap.has(c.file)) symMap.set(c.file, new Set());
  symMap.get(c.file)!.add(c.symbol);
}

  const symbols = [...symMap.entries()]
    .map(([file, set]) => ({ file, names: [...set].slice(0, 12) }))
    .sort((a, b) => b.names.length - a.names.length).slice(0, 25);

  return {
    totalFiles: files.length, totalChunks: chunks.length, filesByLanguage,
    topDirectories, entryPoints: [...new Set(entryPoints)], hubFiles, symbols,
  };
}

export function formatRepoMap(m: RepoMap): string {
  const lines: string[] = [];
  lines.push(`# Repo map - ${m.totalFiles} files, ${m.totalChunks} chunks`);
  lines.push(`Languages: ${Object.entries(m.filesByLanguage).map(([k, v]) => `${k}(${v})`).join(", ")}`);
  lines.push(`\n## Entry points`);
  for (const e of m.entryPoints) lines.push(`- ${e}`);
  lines.push(`\n## Hub files (most referenced)`);
  for (const h of m.hubFiles) lines.push(`- ${h.file}  <- ${h.referencedBy} files`);
  lines.push(`\n## Key symbols by file`);
  for (const s of m.symbols) lines.push(`- ${s.file}: ${s.names.join(", ")}`);
  return lines.join("\n");
}

/**
 * Repo scanner: git-aware-ish file walk. Skips dependencies, build output,
 * binary and oversized files. Detects language from extension.
 */

import { promises as fs } from "node:fs";
import * as path from "node:path";

export interface ScannedFile {
  relPath: string;
  absPath: string;
  language: string;
  size: number;
  content: string;
}

const SKIP_DIRS = new Set([
  "node_modules", ".git", ".hg", ".svn", "dist", "build", "out", "target",
  "vendor", "__pycache__", ".next", ".nuxt", ".cache", "coverage", ".idea",
  ".vscode", "venv", ".venv", "env", ".ember", "tmp", "temp", "logs", "dist-test",
]);

const SKIP_FILES = new Set([
  "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "composer.lock",
  "Gemfile.lock", "poetry.lock", "Cargo.lock", "go.sum",
]);

const LANG_BY_EXT: Record<string, string> = {
  ".ts": "typescript", ".tsx": "typescript", ".js": "javascript", ".jsx": "javascript",
  ".mjs": "javascript", ".cjs": "javascript", ".py": "python", ".go": "go",
  ".rs": "rust", ".java": "java", ".kt": "kotlin", ".cpp": "cpp", ".cc": "cpp",
  ".cxx": "cpp", ".c": "c", ".h": "c-header", ".hpp": "cpp-header", ".cs": "csharp",
  ".rb": "ruby", ".php": "php", ".swift": "swift", ".scala": "scala",
  ".md": "markdown", ".mdx": "markdown", ".sql": "sql", ".sh": "shell",
  ".yml": "yaml", ".yaml": "yaml", ".json": "json", ".toml": "toml",
};

const MAX_TOTAL_FILES = 4000;

/** Optional <root>/.emberignore: one repo-relative path per line. A line
 * matches that exact file, or everything under that directory prefix.
 * Lines starting with # are comments. Use it to keep fixtures, generated
 * snapshots and eval corpora out of the index. */

    const raw = await fs.readFile(path.join(root, ".emberignore"), "utf8");
    return raw.split("\n").map(l => l.trim()).filter(l => l && !l.startsWith("#"));
  } catch { return []; }
}

async function walk(dir: string): Promise<void> {
  if (out.length >= MAX_TOTAL_FILES) return;
  let entries;
  try { entries = await fs.readdir(dir, { withFileTypes: true }); }
  catch { return; }

const abs = path.join(dir, e.name);
if (e.isDirectory()) {
  // Exact ".git" only: startsWith(".git") would also skip ".github",
  // silently dropping workflows, issue templates and docs from the index.
  if (SKIP_DIRS.has(e.name) || e.name === ".git") continue;
  await walk(abs);
} else if (e.isFile()) {
  if (SKIP_FILES.has(e.name) || e.name.endsWith(".min.js")) continue;

const language = LANG_BY_EXT[ext];
if (!language) continue;
let st;
try { st = await fs.stat(abs); } catch { continue; }
if (st.size === 0 || st.size > MAX_FILE_BYTES) continue;
let content: string;
try { content = await fs.readFile(abs, "utf8"); } catch { continue; }
if (content.indexOf("\0") !== -1) continue; // binary sniff

        const relPath = path.relative(root, abs);
        if (isIgnored(relPath)) continue;
        out.push({ relPath, absPath: abs, language, size: st.size, content });
      }
    }
  }
  await walk(root);
  // Deterministic order: chunk ids are assigned sequentially in scan order,
  // so a stable byte-order sort keeps ids reproducible across runs, clones
  // and filesystems (readdir order is arbitrary).
  out.sort((a, b) => (a.relPath < b.relPath ? -1 : a.relPath > b.relPath ? 1 : 0));
  return out;
}

/**
 * Local-first persistence. Everything lives in <repo>/.ember/:
 *   meta.json    - config, counts, embedder identity, timestamps
 *   files.json   - per-file sha1/size at last index (incremental re-index)
 *   chunks.jsonl - one JSON CodeChunk + id per line
 *   vectors.f32  - raw Float32 vector data, row-major, aligned with chunk ids
 *   hnsw.json    - serialized graph topology
 *   notes.jsonl  - cross-session agent notes (see notes.ts)
 * No external database; the directory can be deleted to reset.
 */

import { promises as fs } from "node:fs";
import * as path from "node:path";
import { HnswIndex } from "./hnsw.js";
import type { CodeChunk } from "./chunker.js";

export interface ChunkRecord extends CodeChunk { id: number; }

export interface IndexMeta {
  version: 1;
  repoRoot: string;
  embedderKind: string;
  dim: number;
  chunkCount: number;
  fileCount: number;
  createdAt: string;
  updatedAt: string;
}

constructor(readonly repoRoot: string) {
  this.dir = path.join(repoRoot, ".ember");
}

async exists(): Promise<boolean> {
  try { await fs.access(path.join(this.dir, "meta.json")); return true; }
  catch { return false; }
}

async save(meta: IndexMeta, chunks: ChunkRecord[], vectors: Float32Array[], index: HnswIndex, fileHashes?: FileHashMap): Promise<void> {
  await fs.mkdir(this.dir, { recursive: true });
  await fs.writeFile(path.join(this.dir, "meta.json"), JSON.stringify(meta, null, 2));

  const buf = Buffer.alloc(vectors.length * meta.dim * 4);
  vectors.forEach((v, i) => { Buffer.from(v.buffer, v.byteOffset, meta.dim * 4).copy(buf, i * meta.dim * 4); });
  await fs.writeFile(path.join(this.dir, "vectors.f32"), buf);
  await fs.writeFile(path.join(this.dir, "hnsw.json"), JSON.stringify(index.toJSON()));
  if (fileHashes) await fs.writeFile(path.join(this.dir, "files.json"), JSON.stringify(fileHashes));
}

